// Type-check the declarations generated by wasm-pack for explicit `null` inputs.
// Keep these calls inside an uncalled function: this is a compile-time fixture.
import {
  deriveDiscoveryKeypairs,
  deriveDiscoveryKeypairsWithSecrets,
  discoverAccountsFromMnemonic,
  discoverAccountsFromMnemonicWithSecrets,
  generateAccountAddresses,
  generateAccountCandidates,
  generateAccountCandidatesWithSecrets,
  generateMnemonic,
  type WasmAccount,
  type WasmCiphertext,
  type WasmTransferParams,
  type WasmWithdrawParams,
} from "../../crates/wasm/pkg/krusty_kms_wasm.js";

export function acceptExplicitNulls(
  mnemonic: string,
  account: WasmAccount,
  ciphertext: WasmCiphertext,
  transfer: WasmTransferParams,
  withdraw: WasmWithdrawParams,
): void {
  deriveDiscoveryKeypairs(mnemonic, null);
  deriveDiscoveryKeypairsWithSecrets(mnemonic, null);
  discoverAccountsFromMnemonic(mnemonic, null);
  discoverAccountsFromMnemonicWithSecrets(mnemonic, null);
  generateAccountAddresses(mnemonic, null);
  generateAccountCandidates(mnemonic, null);
  generateAccountCandidatesWithSecrets(mnemonic, null);
  generateMnemonic(null);
  account.decryptBalance(ciphertext, null);
  transfer.bit_size = null;
  withdraw.bit_size = null;
}
